world_checks.check_appointments_have_their_calendar_e:
def check(world):
    state = world.state()
    events = {e["event_id"]: e for e in state.get("calendar_events", [])}
    providers = {p["provider_id"]: p for p in state.get("providers", [])}
    appts = state.get("appointments", [])
    if len(appts) < 20:
        return f"expected at least 20 appointments, found {len(appts)}"
    for a in appts:
        e = events.get(a["calendar_event_id"])
        if e is None:
            return f"appointment {a['appointment_id']} has no calendar event {a['calendar_event_id']}"
        if e["calendar_id"] != providers[a["provider_id"]]["calendar_id"]:
            return f"appointment {a['appointment_id']}'s event is not on {a['provider_id']}'s calendar"
        if (e["start_time"], e["end_time"]) != (a["start_time"], a["end_time"]):
            return f"appointment {a['appointment_id']} and its event disagree on the time"
        if (a["status"] == "cancelled") != (e["status"] == "cancelled"):
            return f"appointment {a['appointment_id']} is {a['status']} but its event is {e['status']}"
    linked = {a["calendar_event_id"] for a in appts}
    provider_cals = {p["calendar_id"] for p in providers.values()}
    for e in events.values():
        if e["calendar_id"] in provider_cals and e["status"] != "cancelled" and e["event_id"] not in linked and e.get("description") != "block":
            return f"event {e['event_id']} on a provider calendar has no clinic appointment and is not a block"
    return None

world_checks.check_appointments_inside_sessions:
def check(world):
    from datetime import date
    state = world.state()
    sessions = state.get("provider_sessions", [])
    for a in state.get("appointments", []):
        d = date.fromisoformat(a["start_time"][:10]); hhmm = a["start_time"][11:16]
        if not any(s["provider_id"] == a["provider_id"] and s["weekday"] == d.weekday() and s["location_id"] == a["location_id"] and s["start_hhmm"] <= hhmm < s["end_hhmm"] for s in sessions):
            return f"appointment {a['appointment_id']} is outside {a['provider_id']}'s sessions at {a['location_id']}"
    return None

world_checks.check_referral_specialties_have_referral:
def check(world):
    state = world.state()
    need = {s["specialty"] for s in state.get("specialties", []) if s["referral_required"]}
    active = {(r["patient_id"], r["specialty"]) for r in state.get("referrals", []) if r["status"] == "active"}
    for a in state.get("appointments", []):
        if a["status"] == "scheduled" and a["specialty"] in need and (a["patient_id"], a["specialty"]) not in active:
            return f"appointment {a['appointment_id']} is {a['specialty']} without an active referral"
    for p in state.get("providers", []):
        if not [x for x in state.get("provider_payers", []) if x["provider_id"] == p["provider_id"]]:
            return f"provider {p['provider_id']} accepts no insurer"
    return None

world_checks.check_mailbox_clinic_consistency:
def check(world):
    import re
    state = world.state()
    msgs = state.get("gmail_messages", [])
    if len(msgs) < 15:
        return "the appointments mailbox has too few messages"
    clinic = "@riverbank-clinics.example"
    practices = ("@westside-medical.example", "@harbour-family-practice.example")
    patients = {p["email"].lower(): p for p in state.get("patients", []) if p.get("email")}
    appts = {a["appointment_id"]: a for a in state.get("appointments", [])}
    refs = {r["referral_id"]: r for r in state.get("referrals", [])}
    for m in msgs:
        text = f"{m['subject']} {m['body']}"
        sender = m["sender"].lower()
        pat = patients.get(sender) or patients.get(m["recipient"].lower())
        if not (sender.endswith(clinic) or sender.endswith(practices) or sender in patients):
            return f"message {m['id']} is from {sender}, who is neither a patient nor a known practice"
        for aid in set(re.findall(r"\bA\d{2}\b", text)):
            if aid not in appts:
                return f"message {m['id']} names appointment {aid}, which does not exist"
            if pat and appts[aid]["patient_id"] != pat["patient_id"]:
                return f"message {m['id']} names {aid}, which is not {pat['patient_id']}'s"
        for rid in set(re.findall(r"\bRF\d{2}\b", text)):
            if rid not in refs:
                return f"message {m['id']} names referral {rid}, which does not exist"
        if pat and pat["full_name"].split()[0] not in text and not sender.endswith(clinic):
            return f"message {m['id']} from {sender} is not signed by {pat['full_name']}"
    return None

world_checks.check_parameters_equal_policy_defaults:
def check(world):
    import json
    state = world.state()
    have = {r["name"]: json.loads(r["value"]) for r in state.get("environment_policy", [])}
    want = {"change_notice_hours": 24, "hold_minutes": 15, "min_notice_hours": 2, "max_horizon_days": 30, "waitlist_enabled": True}
    if have != want:
        return f"environment_policy is {have}, the policy defaults are {want}"
    if not state.get("clock") or state["clock"][0]["now"] != "2026-10-26T09:00:00Z":
        return "the clock is not 2026-10-26T09:00:00Z"
    return None
